SELECT MIN(LOWER(GRADES_LOW)) AS lowest_grade_level
FROM schools
WHERE DISTRICTID = '0632640';

SELECT COUNT(DISTINCT card_id) AS release_promo_card_count
FROM cards
WHERE promotion_type = 'release';

SELECT COUNT(DISTINCT language) AS num_foreign_languages
FROM foreign_data
WHERE card_id IN (
    SELECT id FROM cards WHERE name = 'Swamp'
);

SELECT COUNT(*) AS character_count
FROM superhero
WHERE publisher_id = (
    SELECT publisher_id FROM superhero WHERE name = 'A-Bomb'
)
AND (race IS NULL OR TRIM(race) = '');

SELECT ROUND(AVG(weight_kg), 2) AS avg_female_hero_weight_kg
FROM superhero
WHERE gender = 'Female' AND weight_kg IS NOT NULL;

SELECT MAX("anti_ribonuclear_protein") AS highest_anti_rnp_value
FROM Laboratory
WHERE clinic = 'thrombosis unit outpatient';

SELECT COUNT(*) AS hydrogen_bond_count
FROM bond
WHERE (atom1_id IN (
        SELECT id FROM atom
        WHERE molecule_id = (
            SELECT molecule_id FROM atom WHERE element_symbol = 'Y' LIMIT 1
        )
    ) AND atom2_id IN (
        SELECT id FROM atom
        WHERE element_symbol = 'H'
          AND molecule_id = (
              SELECT molecule_id FROM atom WHERE element_symbol = 'Y' LIMIT 1
          )
    ))
   OR (atom2_id IN (
        SELECT id FROM atom
        WHERE molecule_id = (
            SELECT molecule_id FROM atom WHERE element_symbol = 'Y' LIMIT 1
        )
    ) AND atom1_id IN (
        SELECT id FROM atom
        WHERE element_symbol = 'H'
          AND molecule_id = (
              SELECT molecule_id FROM atom WHERE element_symbol = 'Y' LIMIT 1
          )
    ))
